# Let's analyze the differences more carefully
print("Detailed analysis:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"\n{i}: '{inp}' -> '{outp}'")
    if inp != outp:
        # Find where they start to differ
        pos = 0
        while pos < min(len(inp), len(outp)) and inp[pos] == outp[pos]:
            pos += 1

        if pos < len(inp) and pos < len(outp):
            print(f"  First difference at position {pos}: '{inp[pos]}' -> '{outp[pos]}'")
        elif len(inp) != len(outp):
            print(f"  Length change: {len(inp)} -> {len(outp)}")

        # Check if one string is a substring of the other
        if len(inp) < len(outp):
            # inp is shorter, so outp contains inp plus extra
            extra = outp[len(inp):]
            print(f"  Extra chars in output: '{extra}'")
        elif len(inp) > len(outp):
            # inp is longer, so it contains outp plus extra
            extra = inp[len(outp):]
            print(f"  Extra chars in input: '{extra}'")
        else:
            # Same length - check character by character
            for j in range(len(inp)):
                if inp[j] != outp[j]:
                    print(f"  Position {j}: '{inp[j]}' -> '{outp[j]}'")

